from pathlib import Path
import hashlib,json,datetime
R=Path(__file__).resolve().parents[1];H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
paths=[R/'web/index.html']+[p for root in ['web/src','web/public']for p in(R/root).rglob('*')if p.is_file()]
rows=[{'path':str(p.relative_to(R)),'bytes':p.stat().st_size,'sha256':H(p)}for p in sorted(paths)]
tree=hashlib.sha256(''.join(x['path']+'\0'+x['sha256']+'\n'for x in sorted(rows,key=lambda x:x['path'])).encode()).hexdigest()
anchors=['dist/malabar-hot-coast.html','dist/game.bundle.js','dist/v13-ui-preview.html','dist/v13-ui-frame.html','web/package.json','web/package-lock.json','web/build-standalone.mjs','web/build-ui-preview.mjs','tests/v13/full_gate.log','tests/v13/build.log','tests/recovery/standalone_integrity.json','tests/recovery/native_metadata_final.json','tests/recovery/runtime_payload_audit.json','assets/cars/silver_refinement/freeze.json','assets/showroom/loft_freeze.json']
report={'candidate':'MALABAR V13 candidate1','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'Local source/art/test candidate; exact public CSS, full WebGL, human driving and audio listening acceptance remain separate.','base':'V12 REBUILD1 Sites23, runtime tree302d7e3eeeb8f46626bca5a22dd7722f90c65228e25ecd285033796dbb2a57ca','runtime_tree_sha256':tree,'tree_algorithm':'SHA256 of sorted relative-path + NUL + file SHA256 + newline','runtime_files':rows,'anchors':{n:{'bytes':(R/n).stat().st_size,'sha256':H(R/n)}for n in anchors},'save_boundary':'New garage V13 namespace; validated V12 thenV1 migration with immutable raw backup; no previous namespace writes/deletes. Story uses independent namespace. Optimistic conflict checks, not transactional locking.','limits':['Arcade physics, original stylized car interpretations, not engineering simulation','Short original story slice, not a full cinematic campaign or replay recorder','No multiplayer activation or new online currency authority','New PBR/reflection surfaces still need GPU/performance acceptance on actual browser hardware'],'license':'Approved forward-only original-asset wording correction retained; required OSM/Three/font/dependency notices preserved. No history rewrite or revocation claim.'}
(R/'tests/release').mkdir(parents=True,exist_ok=True)
(R/'tests/release/V13_RELEASE.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'runtime_tree_sha256':tree,'files':len(rows),'standalone':report['anchors']['dist/malabar-hot-coast.html']},indent=2))
